import React, { useState, useMemo } from "react";
import {
  View,
  Text,
  Pressable,
  ScrollView,
  StyleSheet,
  ActivityIndicator,
} from "react-native";
import { useRouter } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import * as Haptics from "expo-haptics";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { useTheme, createStyles } from "@/theme";
import { useCollection, useSetting, useUser } from "@/lib/backend";
import { Card } from "@/components/Card";

interface HabitRecord {
  id: string;
  name: string;
  icon: string;
  category: "Morning" | "Afternoon" | "Evening" | "Anytime";
  frequency: string;
  streak: number;
  bestStreak: number;
  completedToday: boolean;
  completionRate: number;
  reminderTime: string;
  targetDaysPerWeek: number;
  colorTag: string;
  createdAt?: string;
}

const CATEGORIES = ["All", "Morning", "Afternoon", "Evening", "Anytime"] as const;
type CategoryFilter = typeof CATEGORIES[number];

// Icon mapping helper for safety
const getValidIcon = (iconName: string): keyof typeof Ionicons.glyphMap => {
  const map: Record<string, keyof typeof Ionicons.glyphMap> = {
    lotus: "flower-outline",
    meditation: "sparkles-outline",
    water: "water-outline",
    book: "book-outline",
    dumbbell: "barbell-outline",
    run: "walk-outline",
    code: "code-slash-outline",
    journal: "journal-outline",
    sleep: "moon-outline",
    sun: "sunny-outline",
    coffee: "cafe-outline",
    nutrition: "nutrition-outline",
    stretch: "body-outline",
    focus: "disc-outline",
    default: "checkmark-circle-outline",
  };
  return map[iconName.toLowerCase()] || "sparkles-outline";
};

export default function TodayDashboardScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const t = useTheme();
  const s = useStyles();
  const { user } = useUser();

  const [streakFreezeActive] = useSetting("streakFreezeActive", true);
  const [selectedFilter, setSelectedFilter] = useState<CategoryFilter>("All");
  const [selectedDayOffset, setSelectedDayOffset] = useState<number>(0);

  const { data: rawHabits, loading, update, insert } = useCollection("habits");

  // Format today's date banner
  const today = useMemo(() => new Date(), []);

  // Generate 7-day strip (3 days past, today, 3 days future)
  const weekDays = useMemo(() => {
    return [-3, -2, -1, 0, 1, 2, 3].map((offset) => {
      const d = new Date();
      d.setDate(today.getDate() + offset);
      return {
        offset,
        dayNumber: d.getDate(),
        dayName: d.toLocaleDateString("en-US", { weekday: "short" }).toUpperCase(),
        isToday: offset === 0,
        fullDate: d,
      };
    });
  }, [today]);

  const habits = (rawHabits || []) as HabitRecord[];

  // Filtered habits
  const filteredHabits = useMemo(() => {
    if (selectedFilter === "All") return habits;
    return habits.filter((h) => h.category === selectedFilter);
  }, [habits, selectedFilter]);

  // Statistics calculation
  const totalCount = habits.length;
  const completedCount = habits.filter((h) => h.completedToday).length;
  const completionPercent = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;

  // Total streak accumulation
  const topStreak = useMemo(() => {
    if (!habits.length) return 0;
    return Math.max(...habits.map((h) => h.streak || 0));
  }, [habits]);

  const handleToggleHabit = async (habit: HabitRecord) => {
    Haptics.impactAsync(
      habit.completedToday 
        ? Haptics.ImpactFeedbackStyle.Light 
        : Haptics.ImpactFeedbackStyle.Heavy
    );

    const nextState = !habit.completedToday;
    const streakChange = nextState ? 1 : -1;
    const newStreak = Math.max(0, (habit.streak || 0) + streakChange);
    const newBest = Math.max(habit.bestStreak || 0, newStreak);

    await update(habit.id, {
      completedToday: nextState,
      streak: newStreak,
      bestStreak: newBest,
    });
  };

  const handleOpenDetail = (id: string) => {
    router.push({
      pathname: "/habit-detail",
      params: { id },
    });
  };

  const handleCreateSeedHabits = async () => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    const seed = [
      {
        name: "Morning Sunlight & Breath",
        icon: "sun",
        category: "Morning",
        frequency: "Daily",
        streak: 14,
        bestStreak: 21,
        completedToday: true,
        completionRate: 94,
        reminderTime: "07:00 AM",
        targetDaysPerWeek: 7,
        colorTag: t.colors.primary,
      },
      {
        name: "2L Hydration",
        icon: "water",
        category: "Anytime",
        frequency: "Daily",
        streak: 8,
        bestStreak: 12,
        completedToday: false,
        completionRate: 85,
        reminderTime: "11:00 AM",
        targetDaysPerWeek: 7,
        colorTag: t.colors.accent,
      },
      {
        name: "Deep Work (90 Mins)",
        icon: "focus",
        category: "Afternoon",
        frequency: "Weekdays",
        streak: 5,
        bestStreak: 15,
        completedToday: false,
        completionRate: 78,
        reminderTime: "01:30 PM",
        targetDaysPerWeek: 5,
        colorTag: t.colors.secondary || t.colors.accent,
      },
      {
        name: "Read 20 Pages",
        icon: "book",
        category: "Evening",
        frequency: "Daily",
        streak: 22,
        bestStreak: 30,
        completedToday: true,
        completionRate: 90,
        reminderTime: "09:15 PM",
        targetDaysPerWeek: 7,
        colorTag: t.colors.warning,
      },
    ];

    for (const item of seed) {
      await insert(item);
    }
  };

  return (
    <View style={[s.screen, { paddingTop: insets.top }]}>
      {/* Top Header */}
      <View style={s.header}>
        <View style={s.headerLeading}>
          <Text style={s.greetingSubtitle}>
            {today.toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric" })}
          </Text>
          <Text style={s.greetingTitle}>
            Ready, {user?.name ? user.name.split(" ")[0] : "Dorian"}
          </Text>
        </View>

        <View style={s.headerTrailing}>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Streak overview"
            style={s.streakBadge}
            onPress={() => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)}
          >
            <Ionicons name="flame" size={18} color={t.colors.warning} />
            <Text style={s.streakBadgeText}>{topStreak}d</Text>
          </Pressable>

          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Settings"
            onPress={() => {
              Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
              router.push("/settings-profile");
            }}
            style={s.iconButton}
          >
            <Ionicons name="settings-outline" size={20} color={t.colors.text} />
          </Pressable>
        </View>
      </View>

      <ScrollView
        contentContainerStyle={[s.scrollContent, { paddingBottom: insets.bottom + 90 }]}
        showsVerticalScrollIndicator={false}
      >
        {/* Weekly Day Carousel */}
        <View style={s.weekStrip}>
          {weekDays.map((d) => {
            const isSelected = selectedDayOffset === d.offset;
            return (
              <Pressable
                key={d.offset}
                accessibilityRole="button"
                accessibilityLabel={`${d.dayName} ${d.dayNumber}`}
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Selection);
                  setSelectedDayOffset(d.offset);
                }}
                style={[
                  s.dayCell,
                  isSelected && s.dayCellSelected,
                  d.isToday && !isSelected && s.dayCellToday,
                ]}
              >
                <Text
                  style={[
                    s.dayNameText,
                    isSelected && s.dayNameTextSelected,
                    d.isToday && !isSelected && s.dayNameTextToday,
                  ]}
                >
                  {d.dayName}
                </Text>
                <View
                  style={[
                    s.dayNumberBubble,
                    isSelected && s.dayNumberBubbleSelected,
                    d.isToday && !isSelected && s.dayNumberBubbleToday,
                  ]}
                >
                  <Text
                    style={[
                      s.dayNumberText,
                      isSelected && s.dayNumberTextSelected,
                      d.isToday && !isSelected && s.dayNumberTextToday,
                    ]}
                  >
                    {d.dayNumber}
                  </Text>
                </View>
                {/* Active indicator dot */}
                {d.isToday && <View style={[s.todayDot, isSelected && s.todayDotSelected]} />}
              </Pressable>
            );
          })}
        </View>

        {/* Momentum Progress Ring Card */}
        <LinearGradient
          colors={[t.colors.surface, t.colors.surfaceAlt]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={s.progressHeroCard}
        >
          <View style={s.progressHeroContent}>
            <View style={s.heroLeft}>
              <View style={s.tagRow}>
                <View style={s.livePulse} />
                <Text style={s.heroCategoryTag}>DAILY RHYTHM</Text>
              </View>
              <Text style={s.heroTitle}>
                {completedCount === totalCount && totalCount > 0
                  ? "All systems go! 🔥"
                  : `${completedCount} of ${totalCount} completed`}
              </Text>
              <Text style={s.heroSubtitle}>
                {completedCount === totalCount && totalCount > 0
                  ? "Flawless consistency today. Keep the streak alive!"
                  : `${totalCount - completedCount} more habit${totalCount - completedCount === 1 ? "" : "s"} to lock in today's rhythm.`}
              </Text>
            </View>

            {/* Circular Progress Gauge representation */}
            <View style={s.gaugeContainer}>
              <View style={s.gaugeOuterCircle}>
                <View
                  style={[
                    s.gaugeFillCircle,
                    {
                      borderColor: completionPercent === 100 ? t.colors.primary : t.colors.accent,
                    },
                  ]}
                >
                  <Text style={s.gaugePercentage}>{completionPercent}%</Text>
                  <Text style={s.gaugeLabel}>DONE</Text>
                </View>
              </View>
            </View>
          </View>

          {/* Progress Bar Line */}
          <View style={s.progressBarTrack}>
            <View
              style={[
                s.progressBarFill,
                {
                  width: `${Math.min(100, Math.max(0, completionPercent))}%`,
                  backgroundColor: completionPercent === 100 ? t.colors.primary : t.colors.accent,
                },
              ]}
            />
          </View>

          {streakFreezeActive && (
            <View style={s.streakShieldRow}>
              <Ionicons name="shield-checkmark" size={14} color={t.colors.primary} />
              <Text style={s.streakShieldText}>Streak Shield Active: 1 Freeze available</Text>
            </View>
          )}
        </LinearGradient>

        {/* Category Filter Pills */}
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={s.filterRow}
        >
          {CATEGORIES.map((cat) => {
            const isActive = selectedFilter === cat;
            return (
              <Pressable
                key={cat}
                accessibilityRole="button"
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Selection);
                  setSelectedFilter(cat);
                }}
                style={[s.filterPill, isActive && s.filterPillActive]}
              >
                <Text style={[s.filterPillText, isActive && s.filterPillTextActive]}>
                  {cat}
                </Text>
              </Pressable>
            );
          })}
        </ScrollView>

        {/* Habit List Section */}
        <View style={s.habitsSection}>
          <View style={s.sectionHeaderRow}>
            <Text style={s.sectionTitle}>
              {selectedFilter === "All" ? "Today's Routine" : `${selectedFilter} Habits`}
            </Text>
            <Text style={s.sectionBadge}>{filteredHabits.length} habits</Text>
          </View>

          {loading ? (
            <View style={s.loaderWrap}>
              <ActivityIndicator color={t.colors.primary} size="large" />
            </View>
          ) : filteredHabits.length === 0 ? (
            <Card style={s.emptyCard}>
              <Ionicons name="sparkles" size={36} color={t.colors.primary} />
              <Text style={s.emptyTitle}>No habits scheduled</Text>
              <Text style={s.emptySubtitle}>
                {habits.length === 0
                  ? "Get started by initializing recommended habits or adding your first one."
                  : `No ${selectedFilter.toLowerCase()} habits found. Switch filter or add one.`}
              </Text>
              {habits.length === 0 && (
                <Pressable
                  accessibilityRole="button"
                  onPress={handleCreateSeedHabits}
                  style={s.seedButton}
                >
                  <Ionicons name="flash-outline" size={16} color={t.colors.onPrimary} />
                  <Text style={s.seedButtonText}>Add Starter Routine</Text>
                </Pressable>
              )}
            </Card>
          ) : (
            filteredHabits.map((habit) => {
              const isDone = habit.completedToday;
              const iconName = getValidIcon(habit.icon);
              return (
                <Pressable
                  key={habit.id}
                  accessibilityRole="button"
                  accessibilityLabel={`${habit.name}, ${isDone ? "completed" : "not completed"}`}
                  onPress={() => handleOpenDetail(habit.id)}
                  style={({ pressed }) => [
                    s.habitCard,
                    isDone && s.habitCardDone,
                    pressed && s.habitCardPressed,
                  ]}
                >
                  <View style={s.habitCardLeft}>
                    {/* Category / Icon Tile */}
                    <View
                      style={[
                        s.habitIconTile,
                        {
                          backgroundColor: isDone ? t.colors.primarySoft : t.colors.surfaceAlt,
                        },
                      ]}
                    >
                      <Ionicons
                        name={iconName}
                        size={22}
                        color={isDone ? t.colors.primary : t.colors.text}
                      />
                    </View>

                    <View style={s.habitInfo}>
                      <View style={s.habitTitleRow}>
                        <Text
                          numberOfLines={1}
                          style={[s.habitTitle, isDone && s.habitTitleDone]}
                        >
                          {habit.name}
                        </Text>
                      </View>

                      <View style={s.habitMetaRow}>
                        <View style={s.metaBadge}>
                          <Ionicons name="time-outline" size={12} color={t.colors.textMuted} />
                          <Text style={s.metaText}>{habit.reminderTime || habit.category}</Text>
                        </View>

                        <View style={s.metaBadge}>
                          <Ionicons name="flame" size={12} color={t.colors.warning} />
                          <Text style={s.metaStreakText}>{habit.streak || 0}d streak</Text>
                        </View>
                      </View>
                    </View>
                  </View>

                  {/* Complete Action Button */}
                  <Pressable
                    accessibilityRole="button"
                    accessibilityLabel={isDone ? "Mark incomplete" : "Mark complete"}
                    onPress={(e) => {
                      e.stopPropagation();
                      handleToggleHabit(habit);
                    }}
                    hitSlop={8}
                    style={({ pressed }) => [
                      s.checkButton,
                      isDone && s.checkButtonDone,
                      pressed && s.checkButtonPressed,
                    ]}
                  >
                    <Ionicons
                      name={isDone ? "checkmark" : "ellipse-outline"}
                      size={20}
                      color={isDone ? t.colors.onPrimary : t.colors.textMuted}
                    />
                  </Pressable>
                </Pressable>
              );
            })
          )}
        </View>
      </ScrollView>

      {/* Floating Action Button for New Habit */}
      <View style={[s.fabContainer, { bottom: insets.bottom + 18 }]}>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel="Create new habit"
          onPress={() => {
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
            router.push("/create-habit");
          }}
          style={({ pressed }) => [s.fab, pressed && s.fabPressed]}
        >
          <LinearGradient
            colors={[t.colors.primary, t.colors.accent]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={s.fabGradient}
          >
            <Ionicons name="add" size={26} color={t.colors.onPrimary} />
            <Text style={s.fabText}>New Habit</Text>
          </LinearGradient>
        </Pressable>
      </View>
    </View>
  );
}

