import React, { useState, useMemo } from "react";
import {
  View,
  Text,
  Pressable,
  ScrollView,
  Alert,
  Share,
  Platform,
} from "react-native";
import { useRouter, useLocalSearchParams } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import * as Haptics from "expo-haptics";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { useTheme, createStyles } from "@/theme";
import { useRecord, useCollection } from "@/lib/backend";
import { Card } from "@/components/Card";
import { Button } from "@/components/Button";
import { TopBar } from "@/components/TopBar";

interface HabitRecord {
  id: string;
  name: string;
  icon: string;
  category: "Morning" | "Afternoon" | "Evening" | "Anytime";
  frequency: "Daily" | "Weekdays" | "Weekends" | "3x per week" | "5x per week";
  streak: number;
  bestStreak: number;
  completedToday: boolean;
  completionRate: number;
  reminderTime: string;
  targetDaysPerWeek: number;
  colorTag: string;
  isPaused?: boolean;
  createdAt?: string;
}

interface MilestoneRecord {
  id: string;
  habitId: string;
  title: string;
  thresholdDays: number;
  unlocked: boolean;
  unlockedDate?: string;
  rewardBadge: string;
  createdAt?: string;
}

const getValidIcon = (iconName?: string): keyof typeof Ionicons.glyphMap => {
  if (!iconName) return "sparkles-outline";
  const map: Record<string, keyof typeof Ionicons.glyphMap> = {
    lotus: "flower-outline",
    meditation: "sparkles-outline",
    water: "water-outline",
    book: "book-outline",
    dumbbell: "barbell-outline",
    run: "walk-outline",
    code: "code-slash-outline",
    journal: "journal-outline",
    sleep: "moon-outline",
    sun: "sunny-outline",
    coffee: "cafe-outline",
    nutrition: "nutrition-outline",
    stretch: "body-outline",
    focus: "disc-outline",
    sparkle: "sparkles-outline",
    heart: "heart-outline",
    flame: "flame-outline",
  };
  return map[iconName.toLowerCase()] || "sparkles-outline";
};

export default function HabitDetailScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const t = useTheme();
  const s = useStyles();

  const { id } = useLocalSearchParams<{ id?: string }>();

  // Fetch habit record & collection for fallback
  const { data: rawHabit, loading: habitLoading, update: updateHabit, remove: removeHabit } = useRecord(
    "habits",
    id || ""
  );

  const { data: rawMilestones } = useCollection("milestones", {
    where: id ? { habitId: id } : undefined,
  });

  const [activeMonthOffset, setActiveMonthOffset] = useState<number>(0);
  const [remindersEnabled, setRemindersEnabled] = useState<boolean>(true);
  const [isPausedState, setIsPausedState] = useState<boolean>(false);

  const habit = (rawHabit as HabitRecord | null) || {
    id: id || "demo-habit",
    name: "Morning Meditation",
    icon: "lotus",
    category: "Morning",
    frequency: "Daily",
    streak: 28,
    bestStreak: 45,
    completedToday: true,
    completionRate: 92,
    reminderTime: "07:00 AM",
    targetDaysPerWeek: 7,
    colorTag: t.colors.primary,
    isPaused: false,
    createdAt: new Date(Date.now() - 60 * 86400000).toISOString(),
  };

  const milestones = (rawMilestones || []) as MilestoneRecord[];

  // Nearest or recently unlocked milestone
  const activeMilestone = useMemo(() => {
    if (milestones.length > 0) {
      const unlocked = milestones.filter((m) => m.unlocked);
      if (unlocked.length > 0) return unlocked[unlocked.length - 1];
      return milestones[0];
    }
    // Fallback milestone
    return {
      id: "m-sample",
      habitId: habit.id,
      title: "30-Day Flow State",
      thresholdDays: 30,
      unlocked: (habit.streak || 0) >= 30,
      rewardBadge: "trophy-outline",
      unlockedDate: (habit.streak || 0) >= 30 ? new Date().toISOString() : undefined,
    };
  }, [milestones, habit.streak, habit.id]);

  // Calendar Heatmap generation
  const monthData = useMemo(() => {
    const d = new Date();
    d.setMonth(d.getMonth() + activeMonthOffset);
    d.setDate(1);

    const year = d.getFullYear();
    const monthIndex = d.getMonth();
    const monthName = d.toLocaleDateString("en-US", { month: "long", year: "numeric" });

    const firstDayIndex = d.getDay(); // 0 is Sunday
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();

    const today = new Date();
    const isCurrentMonth = today.getFullYear() === year && today.getMonth() === monthIndex;
    const currentDayNum = isCurrentMonth ? today.getDate() : -1;

    // Seed deterministic pseudo-completion history based on habit properties
    const days: { dayNumber: number; completed: boolean; isToday: boolean; isFuture: boolean }[] = [];

    for (let i = 1; i <= daysInMonth; i++) {
      const isFuture = isCurrentMonth && i > currentDayNum;
      let completed = false;

      if (!isFuture) {
        if (isCurrentMonth && i === currentDayNum) {
          completed = !!habit.completedToday;
        } else {
          // Semi-random deterministic check for consistent UI appearance
          const pseudoHash = (i * 17 + habit.name.length * 3 + monthIndex * 11) % 100;
          completed = pseudoHash < (habit.completionRate || 85);
        }
      }

      days.push({
        dayNumber: i,
        completed,
        isToday: isCurrentMonth && i === currentDayNum,
        isFuture,
      });
    }

    // Lead empty days
    const leadingSlots = Array.from({ length: firstDayIndex }, (_, i) => i);

    return {
      monthName,
      leadingSlots,
      days,
      totalCompletionsThisMonth: days.filter((d) => d.completed).length,
      daysInMonth,
    };
  }, [activeMonthOffset, habit.completedToday, habit.name, habit.completionRate]);

  const handleToggleToday = async () => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    const nextCompleted = !habit.completedToday;
    const streakDelta = nextCompleted ? 1 : -1;
    const nextStreak = Math.max(0, (habit.streak || 0) + streakDelta);
    const nextBest = Math.max(habit.bestStreak || 0, nextStreak);

    if (updateHabit) {
      await updateHabit({
        completedToday: nextCompleted,
        streak: nextStreak,
        bestStreak: nextBest,
      });
    }
  };

  const handleTogglePause = async () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    const nextPaused = !isPausedState;
    setIsPausedState(nextPaused);
    if (updateHabit) {
      await updateHabit({ isPaused: nextPaused });
    }
  };

  const handleToggleReminder = () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setRemindersEnabled(!remindersEnabled);
  };

  const handleShare = async () => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    try {
      await Share.share({
        message: `I'm on a ${habit.streak}-day streak with "${habit.name}" on Rhythm! ⚡️ Building momentum one day at a time.`,
        title: `${habit.name} Streak`,
      });
    } catch {
      // ignore dismissals
    }
  };

  const handleDeleteHabit = () => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
    Alert.alert(
      "Delete Habit",
      `Are you sure you want to permanently delete "${habit.name}" and all historical streaks?`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete Habit",
          style: "destructive",
          onPress: async () => {
            Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
            if (removeHabit) {
              await removeHabit();
            }
            router.replace("/today-dashboard");
          },
        },
      ]
    );
  };

  const daysRemainingForMilestone = Math.max(
    0,
    (activeMilestone?.thresholdDays || 30) - (habit.streak || 0)
  );

  return (
    <View style={[s.screen, { paddingTop: insets.top }]}>
      {/* Top Bar */}
      <TopBar
        showBack
        onBack={() => router.back()}
        title=""
        trailing={
          <View style={s.topActions}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Share streak"
              onPress={handleShare}
              style={s.topIconButton}
            >
              <Ionicons name="share-outline" size={20} color={t.colors.text} />
            </Pressable>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Edit habit"
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                router.push({
                  pathname: "/create-habit",
                  params: { id: habit.id },
                });
              }}
              style={s.topIconButton}
            >
              <Ionicons name="create-outline" size={20} color={t.colors.text} />
            </Pressable>
          </View>
        }
      />

      <ScrollView
        contentContainerStyle={[s.scrollContent, { paddingBottom: insets.bottom + 40 }]}
        showsVerticalScrollIndicator={false}
      >
        {/* Habit Hero Header */}
        <View style={s.heroSection}>
          <View style={s.badgeRow}>
            <View
              style={[
                s.categoryTag,
                { backgroundColor: t.colors.surfaceAlt, borderColor: t.colors.border },
              ]}
            >
              <Ionicons
                name="time-outline"
                size={12}
                color={t.colors.primary}
                style={{ marginRight: 4 }}
              />
              <Text style={s.categoryTagText}>{habit.category.toUpperCase()}</Text>
            </View>

            <View style={s.frequencyTag}>
              <Text style={s.frequencyTagText}>{habit.frequency}</Text>
            </View>

            {isPausedState && (
              <View style={s.pausedBadge}>
                <Ionicons name="pause" size={12} color={t.colors.warning} />
                <Text style={s.pausedBadgeText}>PAUSED</Text>
              </View>
            )}
          </View>

          <View style={s.heroTitleRow}>
            <View
              style={[
                s.iconTileLarge,
                {
                  backgroundColor: habit.colorTag ? habit.colorTag + "20" : t.colors.primarySoft,
                  borderColor: habit.colorTag || t.colors.primary,
                },
              ]}
            >
              <Ionicons
                name={getValidIcon(habit.icon)}
                size={34}
                color={habit.colorTag || t.colors.primary}
              />
            </View>
            <View style={s.heroTitleContainer}>
              <Text style={s.habitTitle} numberOfLines={2}>
                {habit.name}
              </Text>
              <Text style={s.habitSubtitle}>
                Target: {habit.targetDaysPerWeek || 7} days/week • Created {new Date(habit.createdAt || Date.now()).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
              </Text>
            </View>
          </View>
        </View>

        {/* Big Streak & Action Banner */}
        <LinearGradient
          colors={[t.colors.surface, t.colors.surfaceAlt]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={s.streakBanner}
        >
          <View style={s.streakBannerHeader}>
            <View style={s.streakBadgeHero}>
              <Ionicons name="flame" size={32} color={t.colors.warning} />
              <View style={s.streakCounterColumn}>
                <Text style={s.streakNumber}>{habit.streak || 0}</Text>
                <Text style={s.streakUnit}>DAY STREAK</Text>
              </View>
            </View>

            {/* Check/Uncheck Quick Action */}
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={habit.completedToday ? "Mark habit incomplete" : "Mark habit complete"}
              onPress={handleToggleToday}
              style={({ pressed }) => [
                s.heroCheckButton,
                habit.completedToday && s.heroCheckButtonActive,
                pressed && { transform: [{ scale: 0.95 }] },
              ]}
            >
              <Ionicons
                name={habit.completedToday ? "checkmark-circle" : "ellipse-outline"}
                size={24}
                color={habit.completedToday ? t.colors.onPrimary : t.colors.textMuted}
              />
              <Text
                style={[
                  s.heroCheckText,
                  habit.completedToday && s.heroCheckTextActive,
                ]}
              >
                {habit.completedToday ? "Done Today" : "Mark Done"}
              </Text>
            </Pressable>
          </View>

          {/* Quick Streak Stats Row */}
          <View style={s.statsDivider} />
          <View style={s.statsGrid}>
            <View style={s.statBox}>
              <Text style={s.statLabel}>Best Record</Text>
              <View style={s.statValueRow}>
                <Ionicons name="trophy-outline" size={15} color={t.colors.accent} />
                <Text style={s.statValue}>{habit.bestStreak || 0}d</Text>
              </View>
            </View>

            <View style={s.statBoxBorder}>
              <Text style={s.statLabel}>Consistency</Text>
              <View style={s.statValueRow}>
                <Ionicons name="analytics-outline" size={15} color={t.colors.primary} />
                <Text style={s.statValue}>{habit.completionRate || 92}%</Text>
              </View>
            </View>

            <View style={s.statBox}>
              <Text style={s.statLabel}>Total Done</Text>
              <View style={s.statValueRow}>
                <Ionicons name="checkmark-done" size={15} color={t.colors.success} />
                <Text style={s.statValue}>
                  {Math.round(((habit.streak || 0) * (habit.completionRate || 90)) / 75) + 18}
                </Text>
              </View>
            </View>
          </View>
        </LinearGradient>

        {/* Milestone Celebration Banner */}
        <Card variant={activeMilestone?.unlocked ? "glass" : "default"} style={s.milestoneCard}>
          <View style={s.milestoneHeader}>
            <View
              style={[
                s.milestoneBadgeCircle,
                {
                  backgroundColor: activeMilestone?.unlocked
                    ? t.colors.primary
                    : t.colors.surfaceAlt,
                },
              ]}
            >
              <Ionicons
                name={activeMilestone?.unlocked ? "sparkles" : "lock-closed-outline"}
                size={20}
                color={activeMilestone?.unlocked ? t.colors.onPrimary : t.colors.textMuted}
              />
            </View>

            <View style={s.milestoneTextContainer}>
              <View style={s.milestoneLabelRow}>
                <Text style={s.milestoneTag}>
                  {activeMilestone?.unlocked ? "MILESTONE UNLOCKED 🎉" : "NEXT MILESTONE"}
                </Text>
                {activeMilestone?.thresholdDays && (
                  <Text style={s.milestoneDaysTag}>{activeMilestone.thresholdDays} Days</Text>
                )}
              </View>

              <Text style={s.milestoneTitle}>{activeMilestone?.title || "Consistency Champion"}</Text>
              <Text style={s.milestoneDesc}>
                {activeMilestone?.unlocked
                  ? "Outstanding discipline! You conquered this streak checkpoint."
                  : `${daysRemainingForMilestone} more consecutive day${daysRemainingForMilestone === 1 ? "" : "s"} to claim this badge.`}
              </Text>
            </View>
          </View>

          {/* Progress to next milestone */}
          {!activeMilestone?.unlocked && (
            <View style={s.milestoneProgressTrack}>
              <View
                style={[
                  s.milestoneProgressFill,
                  {
                    width: `${Math.min(
                      100,
                      Math.max(
                        5,
                        ((habit.streak || 0) / (activeMilestone?.thresholdDays || 30)) * 100
                      )
                    )}%`,
                  },
                ]}
              />
            </View>
          )}
        </Card>

        {/* Heatmap Activity Section */}
        <View style={s.sectionHeaderRow}>
          <View>
            <Text style={s.sectionTitle}>Activity Heatmap</Text>
            <Text style={s.sectionSubtitle}>
              {monthData.totalCompletionsThisMonth} completions in {monthData.monthName}
            </Text>
          </View>

          <View style={s.calendarControls}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Previous month"
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                setActiveMonthOffset((prev) => prev - 1);
              }}
              style={s.navArrowButton}
            >
              <Ionicons name="chevron-back" size={18} color={t.colors.text} />
            </Pressable>

            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Current month"
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                setActiveMonthOffset(0);
              }}
              style={[s.navTodayButton, activeMonthOffset === 0 && s.navTodayButtonActive]}
            >
              <Text
                style={[
                  s.navTodayText,
                  activeMonthOffset === 0 && s.navTodayTextActive,
                ]}
              >
                Now
              </Text>
            </Pressable>

            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Next month"
              disabled={activeMonthOffset >= 0}
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                setActiveMonthOffset((prev) => prev + 1);
              }}
              style={[
                s.navArrowButton,
                activeMonthOffset >= 0 && { opacity: 0.3 },
              ]}
            >
              <Ionicons name="chevron-forward" size={18} color={t.colors.text} />
            </Pressable>
          </View>
        </View>

        {/* Heatmap Grid Card */}
        <Card style={s.calendarCard}>
          {/* Weekday labels */}
          <View style={s.weekDaysRow}>
            {["S", "M", "T", "W", "T", "F", "S"].map((day, i) => (
              <Text key={i} style={s.weekDayLabel}>
                {day}
              </Text>
            ))}
          </View>

          {/* Days Grid */}
          <View style={s.gridContainer}>
            {monthData.leadingSlots.map((slot) => (
              <View key={`lead-${slot}`} style={s.emptyDayCell} />
            ))}

            {monthData.days.map((item) => {
              let cellBg = t.colors.surfaceAlt;
              let borderCol = "transparent";

              if (item.completed) {
                cellBg = habit.colorTag || t.colors.primary;
              } else if (item.isFuture) {
                cellBg = t.colors.background;
              }

              if (item.isToday) {
                borderCol = t.colors.accent;
              }

              return (
                <View
                  key={`day-${item.dayNumber}`}
                  style={[
                    s.calendarDayCell,
                    { backgroundColor: cellBg, borderColor: borderCol },
                    item.isToday && s.todayCellRing,
                    item.isFuture && s.futureCell,
                  ]}
                >
                  <Text
                    style={[
                      s.calendarDayNumber,
                      item.completed && { color: t.colors.onPrimary, fontWeight: "700" },
                      item.isFuture && { color: t.colors.textMuted, opacity: 0.4 },
                    ]}
                  >
                    {item.dayNumber}
                  </Text>
                  {item.completed && (
                    <Ionicons
                      name="checkmark"
                      size={10}
                      color={t.colors.onPrimary}
                      style={s.miniCheck}
                    />
                  )}
                </View>
              );
            })}
          </View>

          {/* Legend */}
          <View style={s.legendRow}>
            <View style={s.legendItem}>
              <View style={[s.legendDot, { backgroundColor: habit.colorTag || t.colors.primary }]} />
              <Text style={s.legendText}>Completed</Text>
            </View>
            <View style={s.legendItem}>
              <View style={[s.legendDot, { backgroundColor: t.colors.surfaceAlt }]} />
              <Text style={s.legendText}>Missed</Text>
            </View>
            <View style={s.legendItem}>
              <View style={[s.legendDot, { borderColor: t.colors.accent, borderWidth: 1.5 }]} />
              <Text style={s.legendText}>Today</Text>
            </View>
          </View>
        </Card>

        {/* Reminder Preferences & Schedule */}
        <Text style={[s.sectionTitle, { marginTop: t.spacing.lg }]}>Reminders & Routine</Text>

        <Card style={s.settingsCard}>
          {/* Reminder Toggle */}
          <View style={s.settingRow}>
            <View style={s.settingIconTile}>
              <Ionicons name="notifications-outline" size={20} color={t.colors.primary} />
            </View>
            <View style={s.settingTextCol}>
              <Text style={s.settingTitle}>Smart Prompt</Text>
              <Text style={s.settingSubtitle}>
                {remindersEnabled ? `Scheduled for ${habit.reminderTime || "08:00 AM"}` : "Notifications muted"}
              </Text>
            </View>
            <Pressable
              accessibilityRole="switch"
              accessibilityState={{ checked: remindersEnabled }}
              onPress={handleToggleReminder}
              style={[
                s.switchToggle,
                remindersEnabled && s.switchToggleActive,
              ]}
            >
              <View
                style={[
                  s.switchThumb,
                  remindersEnabled && s.switchThumbActive,
                ]}
              />
            </Pressable>
          </View>

          <View style={s.cardInnerDivider} />

          {/* Target Frequency */}
          <View style={s.settingRow}>
            <View style={s.settingIconTile}>
              <Ionicons name="calendar-outline" size={20} color={t.colors.accent} />
            </View>
            <View style={s.settingTextCol}>
              <Text style={s.settingTitle}>Frequency Goal</Text>
              <Text style={s.settingSubtitle}>
                {habit.frequency} ({habit.targetDaysPerWeek || 7} days/week)
              </Text>
            </View>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Edit frequency"
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                router.push({
                  pathname: "/create-habit",
                  params: { id: habit.id },
                });
              }}
              style={s.smallPillButton}
            >
              <Text style={s.smallPillButtonText}>Edit</Text>
            </Pressable>
          </View>

          <View style={s.cardInnerDivider} />

          {/* Pause / Resume Habit */}
          <View style={s.settingRow}>
            <View style={s.settingIconTile}>
              <Ionicons
                name={isPausedState ? "play-outline" : "pause-outline"}
                size={20}
                color={t.colors.warning}
              />
            </View>
            <View style={s.settingTextCol}>
              <Text style={s.settingTitle}>
                {isPausedState ? "Resume Habit" : "Pause Tracking"}
              </Text>
              <Text style={s.settingSubtitle}>
                {isPausedState
                  ? "Habit is currently frozen without breaking streak"
                  : "Preserve current streak during vacation or illness"}
              </Text>
            </View>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={isPausedState ? "Resume habit" : "Pause habit"}
              onPress={handleTogglePause}
              style={[s.smallPillButton, isPausedState && s.smallPillButtonActive]}
            >
              <Text
                style={[
                  s.smallPillButtonText,
                  isPausedState && s.smallPillButtonTextActive,
                ]}
              >
                {isPausedState ? "Resume" : "Pause"}
              </Text>
            </Pressable>
          </View>
        </Card>

        {/* Action Buttons: Edit or Delete */}
        <View style={s.bottomActionsContainer}>
          <Button
            title="Edit Habit Configuration"
            variant="secondary"
            icon="create-outline"
            onPress={() => {
              router.push({
                pathname: "/create-habit",
                params: { id: habit.id },
              });
            }}
            fullWidth
            style={{ marginBottom: 12 }}
          />

          <Button
            title="Delete Habit"
            variant="ghost"
            icon="trash-outline"
            textStyle={{ color: t.colors.danger }}
            onPress={handleDeleteHabit}
            fullWidth
          />
        </View>
      </ScrollView>
    </View>
  );
}

