import { Button } from "@/components/Button";

// Available icons
const AVAILABLE_ICONS = [
  { key: "meditation", label: "Zen", ionicon: "sparkles-outline" },
  { key: "lotus", label: "Lotus", ionicon: "flower-outline" },
  { key: "water", label: "Water", ionicon: "water-outline" },
  { key: "book", label: "Book", ionicon: "book-outline" },
  { key: "dumbbell", label: "Fitness", ionicon: "barbell-outline" },
  { key: "run", label: "Run", ionicon: "walk-outline" },
  { key: "code", label: "Code", ionicon: "code-slash-outline" },
  { key: "journal", label: "Journal", ionicon: "journal-outline" },
  { key: "sleep", label: "Sleep", ionicon: "moon-outline" },
  { key: "sun", label: "Morning", ionicon: "sunny-outline" },
  { key: "coffee", label: "Coffee", ionicon: "cafe-outline" },
  { key: "nutrition", label: "Food", ionicon: "nutrition-outline" },
  { key: "stretch", label: "Stretch", ionicon: "body-outline" },
  { key: "focus", label: "Focus", ionicon: "disc-outline" },
  { key: "flame", label: "Fire", ionicon: "flame-outline" },
  { key: "heart", label: "Health", ionicon: "heart-outline" },
] as const;

const CATEGORIES = ["Morning", "Afternoon", "Evening", "Anytime"] as const;
type Category = (typeof CATEGORIES)[number];

type SuggestionPreset = {
  name: string;
  icon: string;
  category: Category;
  targetDays: number;
  colorTag: string;
  time: string;
};

const FREQUENCIES = [
  { label: "Daily", value: "Daily", targetDays: 7 },
  { label: "Weekdays", value: "Weekdays", targetDays: 5 },
  { label: "Weekends", value: "Weekends", targetDays: 2 },
  { label: "3x / week", value: "3x per week", targetDays: 3 },
  { label: "5x / week", value: "5x per week", targetDays: 5 },
] as const;

// Time presets for quick selection
const TIME_PRESETS = [
  "06:30 AM", "07:00 AM", "08:00 AM", "09:00 AM",
  "12:00 PM", "01:30 PM", "05:30 PM", "07:00 PM",
  "09:00 PM", "10:30 PM"
];

export default function CreateHabitScreen() {
  const router = useRouter();
  const params = useLocalSearchParams<{ id?: string }>();
  const isEditing = !!params.id;
  const insets = useSafeAreaInsets();
  const t = useTheme();
  const s = useStyles();

  const suggestionPresets = useMemo<SuggestionPreset[]>(() => [
    { name: "Morning Meditation", icon: "meditation", category: "Morning", targetDays: 7, colorTag: t.colors.primary, time: "07:00 AM" },
    { name: "Read 20 Pages", icon: "book", category: "Evening", targetDays: 7, colorTag: t.colors.accent, time: "09:00 PM" },
    { name: "2L Hydration", icon: "water", category: "Anytime", targetDays: 7, colorTag: t.colors.primary, time: "10:00 AM" },
    { name: "Deep Work (90m)", icon: "focus", category: "Morning", targetDays: 5, colorTag: t.colors.accent, time: "09:30 AM" },
    { name: "Strength Workout", icon: "dumbbell", category: "Afternoon", targetDays: 4, colorTag: t.colors.danger, time: "05:30 PM" },
    { name: "Evening Stretch", icon: "stretch", category: "Evening", targetDays: 7, colorTag: t.colors.accent, time: "10:15 PM" },
  ], [t.colors.primary, t.colors.accent, t.colors.danger]);

  const colorPalette = useMemo(() => [
    t.colors.primary,
    t.colors.accent,
    t.colors.danger,
    t.colors.textMuted,
    t.colors.text,
    t.colors.border,
  ], [t.colors]);

  // Backend connections
  const { insert, update: updateInList } = useCollection("habits");
  const { data: existingHabit, loading: recordLoading } = useRecord("habits", params.id || "");

  // Form State
  const [name, setName] = useState("");
  const [selectedIcon, setSelectedIcon] = useState<string>("meditation");
  const [selectedCategory, setSelectedCategory] = useState<Category>("Morning");
  const [selectedColor, setSelectedColor] = useState<string>(t.colors.primary);
  const [frequency, setFrequency] = useState<string>("Daily");
  const [targetDays, setTargetDays] = useState<number>(7);
  const [enableReminder, setEnableReminder] = useState<boolean>(true);
  const [reminderTime, setReminderTime] = useState<string>("07:30 AM");
  const [isSaving, setIsSaving] = useState(false);
  const [showTimeModal, setShowTimeModal] = useState(false);
  const [customTimeInput, setCustomTimeInput] = useState("");
  const [errors, setErrors] = useState<{ name?: string }>({});

  // Populate data when editing
  useEffect(() => {
    if (existingHabit) {
      setName(existingHabit.name || "");
      setSelectedIcon(existingHabit.icon || "meditation");
      setSelectedCategory((existingHabit.category as Category) || "Morning");
      setSelectedColor(existingHabit.colorTag || t.colors.primary);
      setFrequency(existingHabit.frequency || "Daily");
      setTargetDays(existingHabit.targetDaysPerWeek || 7);
      if (existingHabit.reminderTime) {
        setEnableReminder(true);
        setReminderTime(existingHabit.reminderTime);
      } else {
        setEnableReminder(false);
      }
    }
  }, [existingHabit, t.colors.primary]);

  const handleApplyPreset = (preset: SuggestionPreset) => {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    setName(preset.name);
    setSelectedIcon(preset.icon);
    setSelectedCategory(preset.category as Category);
    setSelectedColor(preset.colorTag);
    setTargetDays(preset.targetDays);
    setReminderTime(preset.time);
    setEnableReminder(true);
    setErrors({});
  };

  const handleFrequencySelect = (item: typeof FREQUENCIES[0]) => {
    Haptics.selectionAsync();
    setFrequency(item.value);
    setTargetDays(item.targetDays);
  };

  const handleSave = async () => {
    const trimmed = name.trim();
    if (!trimmed) {
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
      setErrors({ name: "Please enter a name for your habit" });
      return;
    }

    setIsSaving(true);

    try {
      if (enableReminder && Platform.OS !== "web") {
        const { status } = await Notifications.getPermissionsAsync();
        if (status !== "granted") {
          await Notifications.requestPermissionsAsync();
        }
      }

      const payload = {
        name: trimmed,
        icon: selectedIcon,
        category: selectedCategory,
        colorTag: selectedColor,
        frequency,
        targetDaysPerWeek: targetDays,
        reminderTime: enableReminder ? reminderTime : "",
        updatedAt: new Date().toISOString(),
      };

      if (isEditing && params.id) {
        await updateInList(params.id, payload);
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      } else {
        await insert({
          ...payload,
          streak: 0,
          bestStreak: 0,
          completedToday: false,
          completionRate: 0,
          createdAt: new Date().toISOString(),
        });
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      }

      router.replace("/today-dashboard");
    } catch (err) {
      Alert.alert("Unable to save", "Something went wrong while saving your rhythm.");
    } finally {
      setIsSaving(false);
    }
  };

  const currentIconObj = useMemo(() => {
    return AVAILABLE_ICONS.find((i) => i.key === selectedIcon) || AVAILABLE_ICONS[0];
  }, [selectedIcon]);

  return (
    <Screen
      scrollable
      edges={["top", "bottom"]}
      contentContainerStyle={[s.screenContainer, { paddingBottom: insets.bottom + 40 }]}
    >
      {/* Header */}
      <TopBar
        title={isEditing ? "Edit Rhythm" : "Create Rhythm"}
        subtitle={isEditing ? "Tune your streak parameters" : "Build momentum with a new habit"}
        showBack
        backIcon="close"
        onBack={() => router.back()}
      />

      {/* Live Preview Hero Card */}
      <View style={s.heroPreviewWrapper}>
        <LinearGradient
          colors={[t.colors.surface, t.colors.surfaceAlt]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={s.heroPreviewCard}
        >
          <View style={s.previewBadgeRow}>
            <View style={[s.categoryChip, { backgroundColor: t.colors.surfaceAlt }]}>
              <Ionicons
                name={
                  selectedCategory === "Morning"
                    ? "sunny-outline"
                    : selectedCategory === "Afternoon"
                    ? "partly-sunny-outline"
                    : selectedCategory === "Evening"
                    ? "moon-outline"
                    : "infinite-outline"
                }
                size={12}
                color={selectedColor}
              />
              <Text style={[s.categoryChipText, { color: selectedColor }]}>
                {selectedCategory.toUpperCase()}
              </Text>
            </View>

            <View style={s.freqBadge}>
              <Text style={s.freqBadgeText}>{frequency}</Text>
            </View>
          </View>

          <View style={s.previewMainRow}>
            <View style={[s.previewIconCircle, { backgroundColor: `${selectedColor}20`, borderColor: selectedColor }]}>
              <Ionicons name={currentIconObj.ionicon} size={28} color={selectedColor} />
            </View>
            <View style={s.previewInfo}>
              <Text style={s.previewName} numberOfLines={1}>
                {name.trim() || "Habit Name"}
              </Text>
              <Text style={s.previewMeta}>
                {enableReminder ? `Reminder at ${reminderTime}` : "No notifications"}
              </Text>
            </View>
          </View>
        </LinearGradient>
      </View>

      {/* Suggested Inspiration Presets */}
      {!isEditing && (
        <View style={s.section}>
          <Text style={s.sectionTitle}>QUICK SUGGESTIONS</Text>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={s.presetsScroll}
          >
            {suggestionPresets.map((item, index) => {
              const isSelected = name === item.name;
              return (
                <Pressable
                  key={index}
                  accessibilityRole="button"
                  onPress={() => handleApplyPreset(item)}
                  style={({ pressed }) => [
                    s.presetCard,
                    isSelected && s.presetCardActive,
                    pressed && s.presetCardPressed,
                  ]}
                >
                  <Ionicons
                    name="sparkles"
                    size={14}
                    color={isSelected ? t.colors.primary : t.colors.textMuted}
                    style={s.presetIcon}
                  />
                  <Text style={[s.presetText, isSelected && s.presetTextActive]}>
                    {item.name}
                  </Text>
                </Pressable>
              );
            })}
          </ScrollView>
        </View>
      )}

      {/* Habit Name Input */}
      <View style={s.section}>
        <Text style={s.sectionTitle}>HABIT NAME</Text>
        <Card variant="default" style={s.inputCard}>
          <View style={s.inputRow}>
            <Ionicons name="create-outline" size={20} color={t.colors.textMuted} style={s.inputLeadingIcon} />
            <TextInput
              style={s.textInput}
              placeholder="e.g., Read 20 pages, 30m Run"
              placeholderTextColor={t.colors.textMuted}
              value={name}
              onChangeText={(text) => {
                setName(text);
                if (errors.name) setErrors({});
              }}
              autoCapitalize="sentences"
              returnKeyType="done"
              maxLength={40}
            />
            {name.length > 0 && (
              <Pressable
                accessibilityRole="button"
                accessibilityLabel="Clear text"
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                  setName("");
                }}
                hitSlop={10}
              >
                <Ionicons name="close-circle" size={18} color={t.colors.textMuted} />
              </Pressable>
            )}
          </View>
        </Card>
        {errors.name ? <Text style={s.errorText}>{errors.name}</Text> : null}
      </View>

      {/* Icon Selector */}
      <View style={s.section}>
        <View style={s.sectionHeaderRow}>
          <Text style={s.sectionTitle}>CHOOSE ICON</Text>
          <Text style={s.sectionSubtitle}>{currentIconObj.label}</Text>
        </View>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={s.iconGridScroll}
        >
          {AVAILABLE_ICONS.map((item) => {
            const isSelected = selectedIcon === item.key;
            return (
              <Pressable
                key={item.key}
                accessibilityRole="button"
                accessibilityLabel={item.label}
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                  setSelectedIcon(item.key);
                }}
                style={[
                  s.iconChoiceCircle,
                  isSelected && {
                    backgroundColor: `${selectedColor}25`,
                    borderColor: selectedColor,
                    borderWidth: 2,
                  },
                ]}
              >
                <Ionicons
                  name={item.ionicon}
                  size={22}
                  color={isSelected ? selectedColor : t.colors.textMuted}
                />
              </Pressable>
            );
          })}
        </ScrollView>
      </View>

      {/* Color Accent Picker */}
      <View style={s.section}>
        <Text style={s.sectionTitle}>ENERGY COLOR</Text>
        <View style={s.colorPaletteRow}>
          {colorPalette.map((hex) => {
            const isSelected = selectedColor === hex;
            return (
              <Pressable
                key={hex}
                accessibilityRole="button"
                accessibilityLabel={`Color ${hex}`}
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                  setSelectedColor(hex);
                }}
                style={({ pressed }) => [
                  s.colorCircle,
                  { backgroundColor: hex },
                  isSelected && s.colorCircleSelected,
                  pressed && { opacity: 0.8 },
                ]}
              >
                {isSelected && <Ionicons name="checkmark" size={16} color={t.colors.background} />}
              </Pressable>
            );
          })}
        </View>
      </View>

      {/* Routine Time Grouping */}
      <View style={s.section}>
        <Text style={s.sectionTitle}>TIME OF DAY</Text>
        <View style={s.segmentRow}>
          {CATEGORIES.map((cat) => {
            const isSelected = selectedCategory === cat;
            return (
              <Pressable
                key={cat}
                accessibilityRole="button"
                onPress={() => {
                  Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                  setSelectedCategory(cat);
                }}
                style={[
                  s.segmentButton,
                  isSelected && s.segmentButtonActive,
                ]}
              >
                <Text
                  style={[
                    s.segmentButtonText,
                    isSelected && s.segmentButtonTextActive,
                  ]}
                >
                  {cat}
                </Text>
              </Pressable>
            );
          })}
        </View>
      </View>

      {/* Frequency & Target */}
      <View style={s.section}>
        <View style={s.sectionHeaderRow}>
          <Text style={s.sectionTitle}>FREQUENCY</Text>
          <Text style={s.sectionSubtitle}>{targetDays} days / week</Text>
        </View>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={s.freqScroll}
        >
          {FREQUENCIES.map((freq) => {
            const isSelected = frequency === freq.value;
            return (
              <Pressable
                key={freq.value}
                accessibilityRole="button"
                onPress={() => handleFrequencySelect(freq)}
                style={[
                  s.freqChip,
                  isSelected && [s.freqChipActive, { borderColor: selectedColor }],
                ]}
              >
                <Text style={[s.freqChipText, isSelected && { color: selectedColor, fontWeight: "700" }]}>
                  {freq.label}
                </Text>
              </Pressable>
            );
          })}
        </ScrollView>
      </View>

      {/* Smart Reminder Schedule */}
      <View style={s.section}>
        <Text style={s.sectionTitle}>SMART REMINDERS</Text>
        <Card variant="default">
          <View style={s.reminderToggleRow}>
            <View style={s.reminderToggleLeft}>
              <View style={[s.iconBoxSmall, { backgroundColor: t.colors.surfaceAlt }]}>
                <Ionicons
                  name={enableReminder ? "notifications" : "notifications-off-outline"}
                  size={20}
                  color={enableReminder ? t.colors.primary : t.colors.textMuted}
                />
              </View>
              <View>
                <Text style={s.reminderLabel}>Daily Momentum Ping</Text>
                <Text style={s.reminderSub}>Get notified when it is time to perform</Text>
              </View>
            </View>

            <Switch
              value={enableReminder}
              onValueChange={(val) => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                setEnableReminder(val);
              }}
              trackColor={{ false: t.colors.surfaceAlt, true: t.colors.primary }}
              thumbColor={t.colors.surface}
            />
          </View>

          {enableReminder && (
            <View style={s.reminderTimePickerContainer}>
              <View style={s.divider} />
              <View style={s.timeRow}>
                <Text style={s.timeHeading}>Target Time</Text>
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={`Reminder time: ${reminderTime}`}
                  onPress={() => {
                    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                    setCustomTimeInput(reminderTime);
                    setShowTimeModal(true);
                  }}
                  style={s.timeButton}
                >
                  <Ionicons name="time-outline" size={16} color={t.colors.primary} />
                  <Text style={s.timeButtonText}>{reminderTime}</Text>
                  <Ionicons name="pencil" size={12} color={t.colors.textMuted} />
                </Pressable>
              </View>
            </View>
          )}
        </Card>
      </View>

      {/* CTA Button */}
      <View style={s.ctaContainer}>
        <Button
          title={isEditing ? "Save Rhythm Changes" : "Start Habit & Build Streak"}
          icon={isEditing ? "checkmark-circle-outline" : "flame"}
          size="lg"
          variant="primary"
          loading={isSaving}
          onPress={handleSave}
          fullWidth
        />
      </View>

      {/* Time Picker Modal */}
      <Modal
        visible={showTimeModal}
        transparent
        animationType="fade"
        onRequestClose={() => setShowTimeModal(false)}
      >
        <Pressable
          style={s.modalOverlay}
          onPress={() => setShowTimeModal(false)}
        >
          <Pressable style={s.modalCard} onPress={(e) => e.stopPropagation()}>
            <View style={s.modalHeader}>
              <Text style={s.modalTitle}>Set Reminder Time</Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel="Close time modal"
                onPress={() => setShowTimeModal(false)}
                hitSlop={10}
              >
                <Ionicons name="close" size={22} color={t.colors.textMuted} />
              </Pressable>
            </View>

            <Text style={s.modalSectionLabel}>PRESETS</Text>
            <View style={s.modalPresetsGrid}>
              {TIME_PRESETS.map((time) => {
                const isSelected = reminderTime === time;
                return (
                  <Pressable
                    key={time}
                    accessibilityRole="button"
                    onPress={() => {
                      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
                      setReminderTime(time);
                      setShowTimeModal(false);
                    }}
                    style={[
                      s.modalPresetChip,
                      isSelected && s.modalPresetChipActive,
                    ]}
                  >
                    <Text
                      style={[
                        s.modalPresetText,
                        isSelected && s.modalPresetTextActive,
                      ]}
                    >
                      {time}
                    </Text>
                  </Pressable>
                );
              })}
            </View>

            <View style={s.modalCustomRow}>
              <Text style={s.modalSectionLabel}>CUSTOM TIME (HH:MM AM/PM)</Text>
              <View style={s.modalInputContainer}>
                <TextInput
                  style={s.modalCustomInput}
                  value={customTimeInput}
                  onChangeText={setCustomTimeInput}
                  placeholder="08:45 AM"
                  placeholderTextColor={t.colors.textMuted}
                  autoCapitalize="characters"
                />
                <Button
                  title="Apply"
                  size="sm"
                  onPress={() => {
                    if (customTimeInput.trim()) {
                      setReminderTime(customTimeInput.trim());
                    }
                    setShowTimeModal(false);
                  }}
                />
              </View>
            </View>
          </Pressable>
        </Pressable>
      </Modal>
    </Screen>
  );
}

