  onPress?: () => void;
  style?: StyleProp<ViewStyle>;
  variant?: "default" | "surfaceAlt" | "highlight" | "glass";
  noPadding?: boolean;
}

export function Card({
  children,
  onPress,
  style,
  variant = "default",
  noPadding = false,
}: CardProps) {
  useTheme();
  const s = useStyles();

  const handlePress = () => {
    if (onPress) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      onPress();
    }
  };

  const getVariantStyle = () => {
    switch (variant) {
      case "surfaceAlt":
        return s.surfaceAltCard;
      case "highlight":
        return s.highlightCard;
      case "glass":
        return s.glassCard;
      case "default":
      default:
        return s.defaultCard;
    }
  };

  if (onPress) {
    return (
      <Pressable
        accessibilityRole="button"
        onPress={handlePress}
        style={({ pressed }) => [
          s.base,
          getVariantStyle(),
          noPadding && s.noPadding,
          pressed && s.pressed,
          style,
        ]}
      >
        {children}
      </Pressable>
    );
  }

  return (
    <View
      style={[
        s.base,
        getVariantStyle(),
        noPadding && s.noPadding,
        style,
      ]}
    >
      {children}
    </View>
  );
}

const useStyles = createStyles((t) => ({
  base: {
    borderRadius: t.radius.lg,
    padding: t.spacing.lg,
    borderWidth: 1,
  },
  defaultCard: {
    backgroundColor: t.colors.surface,
    borderColor: t.colors.border,
  },
  surfaceAltCard: {
    backgroundColor: t.colors.surfaceAlt,
    borderColor: t.colors.border,
  },
  highlightCard: {
    backgroundColor: t.colors.surface,
    borderColor: t.colors.primary,
  },
  glassCard: {
    backgroundColor: t.colors.primarySoft,
    borderColor: t.colors.primary,
  },
  noPadding: {
    padding: 0,
  },
  pressed: {
    opacity: 0.9,
    transform: [{ scale: 0.985 }],
  },
}));

