import React from "react";
import {
  Pressable,
  Text,
  ActivityIndicator,
  ViewStyle,
  TextStyle,
  StyleProp,
  View,
} from "react-native";
import { Ionicons } from "@expo/vector-icons";
import * as Haptics from "expo-haptics";
import { createStyles, useTheme } from "@/theme";

type ButtonVariant = "primary" | "secondary" | "ghost" | "destructive" | "accent";
type ButtonSize = "sm" | "md" | "lg";

interface ButtonProps {
  title: string;
  onPress: () => void;
  variant?: ButtonVariant;
  size?: ButtonSize;
  icon?: keyof typeof Ionicons.glyphMap;
  iconPosition?: "left" | "right";
  loading?: boolean;
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<TextStyle>;
  fullWidth?: boolean;
}

export function Button({
  title,
  onPress,
  variant = "primary",
  size = "md",
  icon,
  iconPosition = "left",
  loading = false,
  disabled = false,
  style,
  textStyle,
  fullWidth = false,
}: ButtonProps) {
  const t = useTheme();
  const s = useStyles();

  const handlePress = () => {
    if (disabled || loading) return;
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    onPress();
  };

  const getVariantStyles = () => {
    switch (variant) {
      case "secondary":
        return {
          container: s.secondaryContainer,
          text: s.secondaryText,
          iconColor: t.colors.text,
        };
      case "ghost":
        return {
          container: s.ghostContainer,
          text: s.ghostText,
          iconColor: t.colors.primary,
        };
      case "destructive":
        return {
          container: s.destructiveContainer,
          text: s.destructiveText,
          iconColor: t.colors.onPrimary,
        };
      case "accent":
        return {
          container: s.accentContainer,
          text: s.accentText,
          iconColor: t.colors.onAccent,
        };
      case "primary":
      default:
        return {
          container: s.primaryContainer,
          text: s.primaryText,
          iconColor: t.colors.onPrimary,
        };
    }
  };

  const getSizeStyles = () => {
    switch (size) {
      case "sm":
        return {
          container: s.smContainer,
          text: s.smText,
          iconSize: 16,
        };
      case "lg":
        return {
          container: s.lgContainer,
          text: s.lgText,
          iconSize: 22,
        };
      case "md":
      default:
        return {
          container: s.mdContainer,
          text: s.mdText,
          iconSize: 18,
        };
    }
  };

  const vStyles = getVariantStyles();
  const sStyles = getSizeStyles();

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ disabled: disabled || loading }}
      onPress={handlePress}
      disabled={disabled || loading}
      style={({ pressed }) => [
        s.baseContainer,
        vStyles.container,
        sStyles.container,
        fullWidth && s.fullWidth,
        disabled && s.disabledContainer,
        pressed && !disabled && !loading && s.pressed,
        style,
      ]}
    >
      {loading ? (
        <ActivityIndicator
          size="small"
          color={variant === "ghost" ? t.colors.primary : t.colors.onPrimary}
        />
      ) : (
        <View style={s.contentRow}>
          {icon && iconPosition === "left" && (
            <Ionicons
              name={icon}
              size={sStyles.iconSize}
              color={vStyles.iconColor}
              style={s.leftIcon}
            />
          )}
          <Text
            style={[
              s.baseText,
              vStyles.text,
              sStyles.text,
              disabled && s.disabledText,
              textStyle,
            ]}
          >
            {title}
          </Text>
          {icon && iconPosition === "right" && (
            <Ionicons
              name={icon}
              size={sStyles.iconSize}
              color={vStyles.iconColor}
              style={s.rightIcon}
            />
          )}
        </View>
      )}
    </Pressable>
  );
}

const useStyles = createStyles((t) => ({
  baseContainer: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    borderRadius: t.radius.lg,
    overflow: "hidden",
  },
  fullWidth: {
    width: "100%",
  },
  contentRow: {
