                <Text numberOfLines={1} style={s.inlineSubtitle}>
                  {subtitle}
                </Text>
              )}
            </View>
          )}
        </View>

        {trailing && <View style={s.trailing}>{trailing}</View>}
      </View>

      {largeTitle && title && (
