import React, { ReactNode } from "react";
import { View, Text, Pressable, StyleProp, ViewStyle } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import * as Haptics from "expo-haptics";
import { createStyles, useTheme } from "@/theme";

interface ListRowProps {
  title: string;
  subtitle?: string;
  icon?: keyof typeof Ionicons.glyphMap;
  iconColor?: string;
  iconBgColor?: string;
  trailing?: ReactNode;
  showChevron?: boolean;
  onPress?: () => void;
  style?: StyleProp<ViewStyle>;
  destructive?: boolean;
}

export function ListRow({
  title,
  subtitle,
  icon,
  iconColor,
  iconBgColor,
  trailing,
  showChevron = false,
  onPress,
  style,
  destructive = false,
}: ListRowProps) {
  const t = useTheme();
  const s = useStyles();

  const handlePress = () => {
    if (onPress) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      onPress();
    }
  };

  const content = (
    <>
      {icon && (
        <View
          style={[
            s.iconTile,
            {
              backgroundColor: iconBgColor || t.colors.surfaceAlt,
            },
          ]}
        >
          <Ionicons
            name={icon}
            size={20}
            color={iconColor || (destructive ? t.colors.danger : t.colors.primary)}
          />
        </View>
      )}

      <View style={s.textContainer}>
        <Text
          numberOfLines={1}
          style={[s.title, destructive && s.destructiveText]}
        >
          {title}
        </Text>
        {subtitle && (
          <Text numberOfLines={1} style={s.subtitle}>
            {subtitle}
          </Text>
        )}
      </View>

      {trailing && <View style={s.trailingContainer}>{trailing}</View>}

      {showChevron && (
        <Ionicons
          name="chevron-forward"
          size={18}
          color={t.colors.textMuted}
          style={s.chevron}
        />
      )}
    </>
  );

  if (onPress) {
    return (
      <Pressable
        accessibilityRole="button"
        onPress={handlePress}
        style={({ pressed }) => [s.row, pressed && s.pressed, style]}
      >
        {content}
      </Pressable>
    );
  }

