    color: t.colors.accent,
    fontVariant: ["tabular-nums"],
  },
  track: {
    width: "100%",
    backgroundColor: t.colors.surfaceAlt,
    overflow: "hidden",
  },
  fillContainer: {
    height: "100%",
    overflow: "hidden",
  },
  gradient: {
    flex: 1,
  },
}));

