import React from "react";
import { Pressable, StyleSheet } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import * as Haptics from "expo-haptics";
import { LinearGradient } from "expo-linear-gradient";
import { createStyles, useTheme } from "@/theme";

interface HabitCheckButtonProps {
  completed: boolean;
  onToggle: () => void;
  size?: number;
  disabled?: boolean;
}

export function HabitCheckButton({
  completed,
  onToggle,
  size = 46,
  disabled = false,
}: HabitCheckButtonProps) {
  const t = useTheme();
  const s = useStyles();

  const handlePress = () => {
    if (disabled) return;
    if (!completed) {
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    } else {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    }
    onToggle();
  };

  return (
    <Pressable
      accessibilityRole="checkbox"
      accessibilityState={{ checked: completed, disabled }}
      accessibilityLabel={completed ? "Mark habit incomplete" : "Mark habit completed"}
      onPress={handlePress}
      disabled={disabled}
      style={({ pressed }) => [
        s.container,
        { width: size, height: size, borderRadius: size / 2 },
        pressed && !disabled && s.pressed,
      ]}
      hitSlop={8}
    >
      {completed ? (
        <LinearGradient
          colors={[t.colors.primary, t.colors.accent]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={[s.gradientFill, { borderRadius: size / 2 }]}
        >
          <Ionicons
            name="checkmark-sharp"
            size={size * 0.52}
            color={t.colors.onPrimary}
          />
        </LinearGradient>
      ) : (
        <LinearGradient
          colors={["transparent", "transparent"]}
          style={[
            s.outlineRing,
            {
              width: size,
              height: size,
              borderRadius: size / 2,
              borderColor: t.colors.border,
            },
          ]}
        >
          <Ionicons
            name="checkmark-sharp"
            size={size * 0.44}
            color={t.colors.border}
          />
        </LinearGradient>
      )}
    </Pressable>
  );
}

const useStyles = createStyles((t) => ({
  container: {
    alignItems: "center",
    justifyContent: "center",
  },
  gradientFill: {
    width: "100%",
    height: "100%",
    alignItems: "center",
    justifyContent: "center",
    shadowColor: t.colors.primary,
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.35,
    shadowRadius: 8,
    elevation: 4,
  },
  outlineRing: {
    borderWidth: 2,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: t.colors.surfaceAlt,
  },
  pressed: {
    transform: [{ scale: 0.9 }],
  },
}));

