import React from "react";
import { View, Text, Pressable, StyleProp, ViewStyle } from "react-native";
import * as Haptics from "expo-haptics";
import { createStyles, useTheme } from "@/theme";

interface SegmentOption<T extends string = string> {
  value: T;
  label: string;
  icon?: string;
  badge?: number;
}

interface SegmentedControlProps<T extends string = string> {
  options: SegmentOption<T>[];
  selectedValue: T;
  onSelect: (value: T) => void;
  style?: StyleProp<ViewStyle>;
}

export function SegmentedControl<T extends string = string>({
  options,
  selectedValue,
  onSelect,
  style,
}: SegmentedControlProps<T>) {
  useTheme();
  const s = useStyles();

  const handleSelect = (val: T) => {
    if (val !== selectedValue) {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      onSelect(val);
    }
  };

  return (
    <View style={[s.container, style]}>
      {options.map((option) => {
        const isSelected = option.value === selectedValue;
        return (
          <Pressable
            key={option.value}
            accessibilityRole="tab"
            accessibilityState={{ selected: isSelected }}
            onPress={() => handleSelect(option.value)}
            style={[s.segment, isSelected && s.segmentSelected]}
          >
            <Text style={[s.label, isSelected && s.labelSelected]}>
              {option.label}
            </Text>
            {option.badge !== undefined && option.badge > 0 && (
              <View
                style={[s.badge, isSelected && s.badgeSelected]}
              >
                <Text
                  style={[s.badgeText, isSelected && s.badgeTextSelected]}
                >
                  {option.badge}
                </Text>
              </View>
            )}
          </Pressable>
        );
      })}
    </View>
  );
}

